"use client";

import { amountToNumber, formatINR } from "../../lib/amount";
import { amountToWords } from "../../lib/words";
import { cn } from "./field";

export interface AmountInWordsProps {
  /** A number, or the raw string from an `AmountInput`. */
  value: number | string;
  /** Leading word. Set to `""` to drop it. Default `"Rupees"`. */
  prefix?: string;
  /** Trailing word, as required on cheques. Default `"Only"`. */
  suffix?: string;
  /** Also render the numeric form above the words. */
  showNumeric?: boolean;
  className?: string;
}

/**
 * The amount spelled out in Indian English — lakh and crore, not million.
 * Required on cheques, invoices and loan agreements.
 */
export function AmountInWords({
  value,
  prefix = "Rupees",
  suffix = "Only",
  showNumeric = false,
  className,
}: AmountInWordsProps) {
  const numeric = typeof value === "number" ? value : amountToNumber(value);

  if (numeric === null || !Number.isFinite(numeric)) {
    return null;
  }

  return (
    <div className={cn("space-y-1", className)}>
      {showNumeric && (
        <p className="font-mono text-sm tabular-nums">{formatINR(numeric)}</p>
      )}
      {/* aria-live so the words update audibly as the amount is typed. */}
      <p
        aria-live="polite"
        className="text-sm capitalize leading-relaxed text-neutral-600 dark:text-neutral-400"
      >
        {amountToWords(numeric, { prefix, suffix })}
      </p>
    </div>
  );
}

"use client";

import { type ClassValue, clsx } from "clsx";
import { CircleAlert, Info } from "lucide-react";
import * as React from "react";
import { twMerge } from "tailwind-merge";

/**
 * Shared by every bharat-ui field. Defined here rather than imported from a
 * project's `@/lib/utils` so that installing a component can never overwrite
 * the consumer's own utils file.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export type FieldTone = "error" | "hint" | "muted";

export interface FieldProps {
  id: string;
  /** Id of the element holding the message; wire this into aria-describedby. */
  messageId: string;
  label?: string;
  /** Resolved message text — an error, a warning, or the fallback description. */
  message?: string;
  tone?: FieldTone;
  className?: string;
  children: React.ReactNode;
}

/** Label + control + message, with the aria plumbing already correct. */
export function Field({
  id,
  messageId,
  label,
  message,
  tone = "muted",
  className,
  children,
}: FieldProps) {
  return (
    <div className={cn("w-full", className)}>
      {label && (
        <label htmlFor={id} className="mb-1.5 block text-sm font-medium">
          {label}
        </label>
      )}

      {children}

      {message && (
        <p
          id={messageId}
          // Only errors interrupt a screen reader; hints are read on focus.
          role={tone === "error" ? "alert" : undefined}
          className={cn(
            "mt-1.5 flex items-start gap-1.5 text-xs",
            tone === "error"
              ? "text-red-600 dark:text-red-400"
              : "text-neutral-500 dark:text-neutral-400",
          )}
        >
          {tone === "error" ? (
            <CircleAlert className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : tone === "hint" ? (
            <Info className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : null}
          {message}
        </p>
      )}
    </div>
  );
}

/** Border/ring classes shared by every text control, keyed on validity. */
export function controlClasses(state: {
  error?: boolean;
  success?: boolean;
}): string {
  return cn(
    "h-10 w-full rounded-lg border bg-transparent px-3 py-2 font-mono text-sm outline-none transition",
    "placeholder:font-sans placeholder:text-neutral-400 dark:placeholder:text-neutral-600",
    "disabled:cursor-not-allowed disabled:opacity-50",
    "focus-visible:ring-[3px]",
    state.error
      ? "border-red-500 focus-visible:ring-red-500/20"
      : state.success
        ? "border-emerald-500 focus-visible:ring-emerald-500/20"
        : "border-neutral-300 focus-visible:border-neutral-900 focus-visible:ring-neutral-900/10 dark:border-neutral-700 dark:focus-visible:border-neutral-300 dark:focus-visible:ring-neutral-100/10",
  );
}

export interface ValidationLike {
  valid: boolean;
  error?: { message: string };
}

/**
 * The controlled/uncontrolled + touched + report-upward logic every field here
 * needs. Kept in one place so all of them behave identically: errors appear on
 * blur by default, then update live once the user has been warned.
 */
export function useFieldState<T extends ValidationLike>(options: {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: T) => void;
  validate: (raw: string) => T;
  /** Optional input mask applied on every keystroke. */
  transform?: (raw: string) => string;
  validateOn?: "blur" | "change";
}) {
  const {
    value: controlled,
    defaultValue = "",
    onValueChange,
    onValidationChange,
    validate,
    transform,
    validateOn = "blur",
  } = options;

  const isControlled = controlled !== undefined;
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue);
  const value = isControlled ? controlled : uncontrolled;
  const [touched, setTouched] = React.useState(false);

  const result = React.useMemo(() => validate(value), [value, validate]);

  // Report upward only when the outcome actually changes, so consumers can put
  // setState directly in the callback without a render loop.
  const lastReported = React.useRef<string>("");
  React.useEffect(() => {
    const key = JSON.stringify(result);
    if (key === lastReported.current) return;
    lastReported.current = key;
    onValidationChange?.(result);
  }, [result, onValidationChange]);

  const setValue = React.useCallback(
    (next: string) => {
      const masked = transform ? transform(next) : next;
      if (!isControlled) setUncontrolled(masked);
      onValueChange?.(masked);
    },
    [isControlled, onValueChange, transform],
  );

  const shouldValidate = validateOn === "change" || touched;
  const error =
    shouldValidate && value.trim() !== "" ? result.error?.message : undefined;

  return {
    value,
    setValue,
    result,
    touched,
    markTouched: () => setTouched(true),
    error,
    success: result.valid,
  };
}

/** Small right-aligned badge inside a control (bank name, entity type, …). */
export function FieldBadge({ children }: { children: React.ReactNode }) {
  return (
    <span className="pointer-events-none absolute right-2 top-1/2 flex max-w-[45%] -translate-y-1/2 items-center gap-1 truncate rounded-full bg-emerald-500/10 px-2 py-0.5 text-xs font-medium text-emerald-700 dark:text-emerald-400">
      {children}
    </span>
  );
}

/**
 * Indian number formatting.
 *
 * The Indian numbering system groups the last three digits, then every two
 * after that — 12,34,567 where most locales would write 1,234,567. Getting this
 * wrong is the single most common localisation bug in Indian products, and
 * `Intl.NumberFormat("en-IN")` gets it right, so we lean on it rather than
 * hand-rolling the grouping.
 */

export interface AmountParts {
  /** Digits only, no separators. Empty string when there's no integer part. */
  integer: string;
  /** Up to two digits, no leading dot. Empty when no decimal was typed. */
  fraction: string;
  /** True when the user has typed the decimal point but no digits yet. */
  trailingPoint: boolean;
}

/**
 * Split raw user input into parts. Tolerant by design: strips currency symbols,
 * spaces and existing separators so pasting "₹ 1,23,456.50" works.
 */
export function parseAmountInput(raw: string): AmountParts {
  const cleaned = raw.replace(/[^\d.]/g, "");
  const firstDot = cleaned.indexOf(".");

  if (firstDot === -1) {
    return { integer: cleaned, fraction: "", trailingPoint: false };
  }

  const integer = cleaned.slice(0, firstDot);
  // Ignore any further dots the user typed, and cap paise at two digits.
  const fraction = cleaned
    .slice(firstDot + 1)
    .replace(/\./g, "")
    .slice(0, 2);

  return { integer, fraction, trailingPoint: fraction.length === 0 };
}

/** Group an integer digit-string the Indian way. `"1234567"` → `"12,34,567"`. */
export function groupIndian(digits: string): string {
  const normalised = digits.replace(/^0+(?=\d)/, "");
  if (normalised.length <= 3) return normalised;
  return new Intl.NumberFormat("en-IN").format(BigInt(normalised));
}

/**
 * Format raw input for display, preserving what the user is mid-way through
 * typing (a trailing `.`, a single paise digit) instead of snapping to 2dp.
 */
export function formatAmountInput(raw: string): string {
  const { integer, fraction, trailingPoint } = parseAmountInput(raw);
  if (!integer && !fraction && !trailingPoint) return "";

  const grouped = groupIndian(integer || "0");
  if (trailingPoint) return `${grouped}.`;
  if (fraction) return `${grouped}.${fraction}`;
  return grouped;
}

/** Numeric value of raw input, or `null` if there's nothing usable. */
export function amountToNumber(raw: string): number | null {
  const { integer, fraction } = parseAmountInput(raw);
  if (!integer && !fraction) return null;
  const value = Number(`${integer || "0"}.${fraction || "0"}`);
  return Number.isFinite(value) ? value : null;
}

/** Whole paise, avoiding float drift. Use this when talking to a payments API. */
export function amountToPaise(raw: string): number | null {
  const { integer, fraction } = parseAmountInput(raw);
  if (!integer && !fraction) return null;
  const paise = `${fraction}00`.slice(0, 2);
  return Number(integer || "0") * 100 + Number(paise);
}

/** `123456.5` → `"₹1,23,456.50"`. */
export function formatINR(
  value: number,
  options: { paise?: boolean } = {},
): string {
  return new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency: "INR",
    minimumFractionDigits: options.paise === false ? 0 : 2,
    maximumFractionDigits: options.paise === false ? 0 : 2,
  }).format(value);
}

/**
 * Render an amount the way Indian finance writes it in prose — "₹1.2 L",
 * "₹3.5 Cr". Useful for summaries; never for an editable field.
 */
export function formatIndianShort(value: number): string {
  const abs = Math.abs(value);
  const sign = value < 0 ? "-" : "";
  const trim = (n: number) => n.toFixed(2).replace(/\.?0+$/, "");

  if (abs >= 1_00_00_000) return `${sign}₹${trim(abs / 1_00_00_000)} Cr`;
  if (abs >= 1_00_000) return `${sign}₹${trim(abs / 1_00_000)} L`;
  if (abs >= 1_000) return `${sign}₹${trim(abs / 1_000)} K`;
  return `${sign}₹${trim(abs)}`;
}

export type AmountErrorCode =
  | "empty"
  | "not_a_number"
  | "below_min"
  | "above_max";

export interface AmountResult {
  valid: boolean;
  value: number | null;
  paise: number | null;
  formatted: string;
  error?: { code: AmountErrorCode; message: string };
}

export function validateAmount(
  raw: string,
  bounds: { min?: number; max?: number } = {},
): AmountResult {
  const value = amountToNumber(raw);
  const paise = amountToPaise(raw);
  const formatted = formatAmountInput(raw);
  const base = { value, paise, formatted };

  if (!raw.trim()) {
    return {
      ...base,
      valid: false,
      error: { code: "empty", message: "Enter an amount." },
    };
  }
  if (value === null) {
    return {
      ...base,
      valid: false,
      error: { code: "not_a_number", message: "That isn't a valid amount." },
    };
  }
  if (bounds.min !== undefined && value < bounds.min) {
    return {
      ...base,
      valid: false,
      error: {
        code: "below_min",
        message: `Enter at least ${formatINR(bounds.min, { paise: false })}.`,
      },
    };
  }
  if (bounds.max !== undefined && value > bounds.max) {
    return {
      ...base,
      valid: false,
      error: {
        code: "above_max",
        message: `Enter no more than ${formatINR(bounds.max, { paise: false })}.`,
      },
    };
  }

  return { ...base, valid: true };
}

/**
 * Numbers to words, Indian style — lakh and crore rather than million and
 * billion. Cheques, invoices and loan agreements all require the amount in
 * words, and every Indian product ends up writing this function badly.
 *
 * `123456` → "One Lakh Twenty Three Thousand Four Hundred Fifty Six"
 */

const ONES = [
  "",
  "One",
  "Two",
  "Three",
  "Four",
  "Five",
  "Six",
  "Seven",
  "Eight",
  "Nine",
  "Ten",
  "Eleven",
  "Twelve",
  "Thirteen",
  "Fourteen",
  "Fifteen",
  "Sixteen",
  "Seventeen",
  "Eighteen",
  "Nineteen",
];

const TENS = [
  "",
  "",
  "Twenty",
  "Thirty",
  "Forty",
  "Fifty",
  "Sixty",
  "Seventy",
  "Eighty",
  "Ninety",
];

/** 0–99. */
function twoDigits(n: number): string {
  if (n < 20) return ONES[n];
  const tens = TENS[Math.floor(n / 10)];
  const ones = ONES[n % 10];
  return ones ? `${tens} ${ones}` : tens;
}

/** 0–999. */
function threeDigits(n: number): string {
  const hundreds = Math.floor(n / 100);
  const rest = n % 100;
  const parts: string[] = [];
  if (hundreds) parts.push(`${ONES[hundreds]} Hundred`);
  if (rest) parts.push(twoDigits(rest));
  return parts.join(" ");
}

/**
 * Integer to Indian words. Groups are crore / lakh / thousand / hundreds —
 * note the 2-2-3 split, not the Western 3-3-3.
 */
export function numberToIndianWords(value: number): string {
  if (!Number.isFinite(value)) return "";
  const n = Math.floor(Math.abs(value));
  if (n === 0) return "Zero";

  const parts: string[] = [];

  // Anything at or above 100 crore is expressed as a multiple of crore too,
  // so recurse on the crore count rather than inventing a bigger unit.
  const crore = Math.floor(n / 1_00_00_000);
  const lakh = Math.floor((n % 1_00_00_000) / 1_00_000);
  const thousand = Math.floor((n % 1_00_000) / 1000);
  const rest = n % 1000;

  if (crore) {
    parts.push(
      `${crore > 999 ? numberToIndianWords(crore) : threeDigits(crore)} Crore`,
    );
  }
  if (lakh) parts.push(`${twoDigits(lakh)} Lakh`);
  if (thousand) parts.push(`${twoDigits(thousand)} Thousand`);
  if (rest) parts.push(threeDigits(rest));

  return (value < 0 ? `Minus ${parts.join(" ")}` : parts.join(" ")).trim();
}

/**
 * Full rupees-and-paise phrasing for a cheque or invoice.
 * `1234.50` → "Rupees One Thousand Two Hundred Thirty Four and Fifty Paise Only"
 */
export function amountToWords(
  value: number,
  options: { prefix?: string; suffix?: string } = {},
): string {
  const { prefix = "Rupees", suffix = "Only" } = options;
  const negative = value < 0;
  const abs = Math.abs(value);

  const rupees = Math.floor(abs);
  // Round rather than truncate, so 0.999 doesn't silently become 99 paise.
  const paise = Math.round((abs - rupees) * 100);

  const parts = [prefix, negative ? "Minus" : "", numberToIndianWords(rupees)];
  if (paise > 0) parts.push("and", numberToIndianWords(paise), "Paise");
  parts.push(suffix);

  return parts.filter(Boolean).join(" ").replace(/\s+/g, " ").trim();
}
